  "resume": "Je jouais ou je jouai ? Passez à « il » : il jouait, il joua.",
  "niveau": "college",
  "fiche": "Avec **je**, plusieurs temps se terminent par un son proche : **-ai** ou **-ais**. **Passez à « il »** pour savoir :\n- il jou**ait** (imparfait) → je jou**ais**\n- il jouer**ait** (conditionnel) → je jouer**ais**\n- il jou**a** (passé simple) → je jou**ai**\n- il jouer**a** (futur) → je jouer**ai**\n\n**Le verbe avoir** : **j'ai** (il a). « J'ais » n'existe pas.\n\n**Le piège** : l'imparfait (je jouais) est le temps le plus courant pour raconter une habitude ou décrire : quand j'étais petit, je **jouais** souvent dehors.\n\n**Pour aller plus loin**\n- Au **subjonctif**, le verbe avoir s'écrit **que j'aie** : il faut que j'**aie** du courage.\n- Le passé simple en **-ai** s'emploie surtout dans les récits écrits : je **marchai** longtemps, puis je **trouvai** un abri.",
