  "bref": "Le conditionnel passé exprime un **regret** ou une **hypothèse qui ne s'est pas réalisée** :\n> j'**aurais** dû, tu **aurais** pu, si j'avais su, je **serais** venu.\n\nOn l'entend comme le futur antérieur (j'**aurai** fini). Passez à **nous** : nous **aurions** dû (conditionnel) / nous **aurons** fini (futur)."
