  "resume": "Les mêmes terminaisons pour tous les verbes : -ais, -ais, -ait…",
  "niveau": "college",
  "fiche": "L'imparfait a **les mêmes terminaisons pour tous les verbes** : **-ais, -ais, -ait, -ions, -iez, -aient**.\n\n**Le radical** est celui de « nous » au présent :\n> nous finissons → je finiss**ais** ; nous prenons → je pren**ais** ; nous faisons → je fais**ais**\nSeule exception : **être** → j'**étais**.\n\n**Pièges** :\n- avec les verbes en **-ier** et **-yer**, on garde le i ou le y du radical **et** celui de la terminaison : nous étud**ii**ons, vous cr**ii**ez, nous voy**i**ons ;\n- avec manger et commencer, on garde le e ou le ç devant a : je mang**e**ais, il commen**ç**ait.",
