  "titre": "la, l'a ou là",
  "resume": "L'article, le verbe avoir ou le lieu ? Trois tests simples.",
  "niveau": "college",
  "fiche": "- **la** est un déterminant (**la** porte) ou un pronom (je **la** vois). Au masculin ou au pluriel, on dirait **le** ou **les**.\n- **l'a** est le pronom « l' » suivi du verbe **avoir** : il **l'a** vu. On peut dire **l'avait**.\n- **là** indique un lieu : reste **là**. On peut dire **ici**.\n\n**Le test** : essayez **le / les**, puis **l'avait**, puis **ici**.\n> Je la connais. → Je le connais ✔ → **la**\n> Elle l'a perdu. → Elle l'avait perdu ✔ → **l'a**\n> Il est là. → Il est ici ✔ → **là**\n\n**Les pièges** :\n- Après **l'a**, il y a un participe passé : il l'a **fermé**, elle l'a **reçu**.\n- Dans une question : est-ce qu'il est **là** ? (est-ce qu'il est ici ?)\n\n**Pour aller plus loin**\n- Avec **tu**, le verbe avoir s'écrit **as** : tu **l'as** vu (tu l'avais vu).\n- **-là** s'attache à un nom ou à un pronom par un trait d'union : ce jour-**là**, cette année-**là**, celui-**là**.\n- **las** (féminin : lasse) signifie « fatigué » : il est **las** d'attendre.",
