  "niveau": "college",
  "fiche": "- **ou** (sans accent) propose un choix. On peut le remplacer par **ou bien** : fromage **ou** dessert.\n- **où** (avec accent) indique un **lieu** ou un **moment** : **où** vas-tu ? la ville **où** je vis, le jour **où** il est parti.\n\n**Le test** : remplacez par **ou bien**. Si la phrase reste correcte, écrivez **ou**. Sinon, écrivez **où**.\n> Tu viens ou tu restes ? → ou bien tu restes ✔ → **ou**\n> La ville où j'habite. → la ville ou bien j'habite ✘ → **où**\n\n**Les pièges** :\n- **ou** peut signifier « sinon » : dépêche-toi, **ou** tu seras en retard (ou bien tu seras en retard).\n- Après un verbe comme savoir, demander, montrer : dis-moi **où** tu habites.\n\n**Pour aller plus loin**\n- **où** indique aussi le temps : le jour **où**, au moment **où**, l'année **où**.\n- Expressions avec **où** : d'**où**, par **où**, là **où**, n'importe **où**, partout **où**.\n- **que… ou non** : que tu le veuilles **ou** non (ou bien non).",
