  "resume": "Conjecture ou conjoncture ? Éminent ou imminent ?",
  "niveau": "superieur",
  "fiche": "Les paronymes sont des mots qui se ressemblent mais n'ont pas le même sens.\n- **conjecture** (hypothèse) / **conjoncture** (situation d'ensemble)\n- **éminent** (remarquable) / **imminent** (qui va arriver très bientôt)\n- **perpétrer** (commettre un crime) / **perpétuer** (faire durer)\n- **infecter** (contaminer) / **infester** (envahir en grand nombre)\n- **infliger** (imposer une peine) / **affliger** (causer du chagrin)\n- **effraction** (entrée en forçant) / **infraction** (violation d'une règle)\n- **acception** (sens d'un mot) / **acceptation** (fait d'accepter)\n- **inclinaison** (pente d'une chose) / **inclination** (penchant, goût)\n- **induire** en erreur (tromper) / **enduire** (recouvrir d'un enduit)\n\n**Pour aller plus loin**\n- **précepteur** (qui instruit un enfant) / **percepteur** (qui perçoit les impôts)\n- **collision** (choc) / **collusion** (entente secrète)",
