  "resume": "Fatiguant ou fatigant ? Convainquant ou convaincant ?",
  "niveau": "superieur",
  "fiche": "- Le **participe présent** exprime une action. Il est **invariable** et se termine toujours en **-ant**. Il peut avoir un complément.\n> En le convainquant de rester… Le jour précédant la fête…\n- L'**adjectif verbal** exprime une qualité. Il **s'accorde**, et son orthographe change parfois.\n> Des arguments convaincants. Un travail fatigant.\n\n**Paires à connaître** (participe / adjectif) :\n- fatiguant / fatigant, convainquant / convaincant, provoquant / provocant, communiquant / communicant\n- négligeant / négligent, précédant / précédent, différant / différent, excellant / excellent, influant / influent, équivalant / équivalent\n\n**L'astuce** : si vous pouvez ajouter « très », c'est l'adjectif.\n\n**Pour aller plus loin**\n- **équivalant** (participe) / **équivalent** (adjectif) ; **influant** / **influent**.",
