  "titre": "Participe passé : pris, fini, dit, mis",
  "resume": "J'ai pris (et non prit) : le test du féminin donne la lettre finale.",
  "niveau": "college",
  "fiche": "Le participe passé se termine souvent par une **lettre muette** : pris, mis, dit, écrit… Pour la trouver, **mettez le participe au féminin** :\n> une chose **prise** → **pris** ; une chose **mise** → **mis** ; une chose **dite** → **dit** ; une lettre **écrite** → **écrit** ; une chose **permise** → **permis**\n> une tâche **finie** → **fini** ; une chose **choisie** → **choisi** (aucune consonne)\n\n**Les pièges** :\n- Après **avoir**, c'est toujours le **participe** : j'ai **pris**, il a **fini**, vous avez **dit**.\n- Ne confondez pas avec les formes conjuguées : il **prit** (passé simple), il **finit** (présent), tu **dis** (présent).\n\n**Pour aller plus loin**\n- Les participes en **-u** : vu, cru, su, lu, bu (féminin : vue, crue, sue, lue, bue).\n- Les verbes en **-ir** du 2e groupe ont un participe en **-i** : fini, choisi, réussi, grandi.\n- Quelques participes courants : **conduit** (conduite), **inclus** (incluse), **conclu** (conclue), **acquis** (acquise).",
