  "niveau": "college",
  "fiche": "- **sais** et **sait** sont le verbe **savoir**. On peut les remplacer par **savait** :\n  - avec **je** et **tu** : je **sais**, tu **sais** ;\n  - avec **il, elle, on** ou un nom : il **sait**, ma sœur **sait**.\n- **c'est** veut dire « cela est » : **c'est** facile.\n- **s'est** est formé du pronom « se » et de l'auxiliaire être, devant un participe passé : il **s'est** levé.\n\n**Le test** : remplacez par **savait**, puis par **cela est**.\n> Je sais nager. → Je savais nager ✔ → **sais**\n> C'est facile. → Cela est facile ✔ → **c'est**\n\n**Le piège** : « Je sais » et « je c'est » se prononcent pareil. Après **je**, c'est le verbe savoir : je **sais**.\n\n**Pour aller plus loin**\n- Dans une question, le sujet passe après le verbe : **sais**-tu nager ? que **sait**-il ?\n- Expressions : **qui sait** ? ; on ne **sait** jamais ; je ne **sais** quoi.",
