  "resume": "Déterminant, pronom ou adverbe : tout ne s'accorde pas toujours.",
  "niveau": "lycee",
  "fiche": "**Tout déterminant ou pronom** s'accorde avec le nom qu'il accompagne ou remplace.\n> tous les jours, toutes les filles, ils sont tous venus\n\n**Tout adverbe** signifie « entièrement, très ». Il est **invariable** :\n> Ils sont tout étonnés. Elle est tout heureuse.\n\n**Exception** : devant un adjectif féminin qui commence par une **consonne** ou un **h aspiré**, l'adverbe s'accorde (pour l'oreille).\n> Elle est toute rouge. Elles sont toutes honteuses.\n\nDevant une voyelle ou un h muet, il reste invariable : elles sont tout heureuses.\n\n**Pour aller plus loin**\n- **Toute autre** solution (= n'importe quelle autre) ≠ une **tout autre** affaire (= complètement différente).\n- De **tous** côtés.",
