  "bref": "Le radical de ces verbes change pour garder le même son :\n- **-cer** : **ç** devant a et o → nous commen**ç**ons ;\n- **-ger** : **ge** devant a et o → nous man**ge**ons ;\n- **-eler / -eter** : j'ach**è**te, mais j'appe**ll**e, je je**tt**e ;\n- **-yer** : **i** devant un e muet → j'emplo**i**e."
